"use client";

import Link from "next/link";
import { useCallback, useEffect, useMemo, useState } from "react";
import { Activity, AlertTriangle, ArrowRight, BarChart3, CheckCircle2, Clock3, Download, FlaskConical, Grid3X3, HeartPulse, Network, Pause, Play, RefreshCw, Settings2, ShieldCheck, Sparkles, Upload } from "lucide-react";
import styles from "@/app/orchestration/orchestration.module.css";

type Tab = "overview" | "health" | "relationships" | "coverage" | "automation" | "actions" | "experiments" | "activity" | "setup";
const TABS: Array<{ id: Tab; label: string }> = [{ id: "overview", label: "Overview" }, { id: "health", label: "Health" }, { id: "relationships", label: "Relationships" }, { id: "coverage", label: "Coverage" }, { id: "automation", label: "Automation" }, { id: "actions", label: "Smart Actions" }, { id: "experiments", label: "Experiments" }, { id: "activity", label: "Activity" }, { id: "setup", label: "Setup & Safety" }];

async function request(path: string, init?: RequestInit) {
  const response = await fetch(path, { cache: "no-store", headers: { "Content-Type": "application/json", ...(init?.headers || {}) }, ...init });
  const contentType = response.headers.get("content-type") || "";
  const data = contentType.includes("json") ? await response.json() : await response.text();
  if (!response.ok) throw new Error(data?.error?.message || data?.error || data?.message || "Request failed.");
  return data;
}
function when(value?: string | null) { return value ? new Date(value).toLocaleString() : "Not available"; }
function pct(value?: number | null) { return value == null ? "No data" : `${Math.round(value * 10) / 10}%`; }
function words(value: string) { return value.replaceAll("_", " ").toLowerCase().replace(/^./, (letter) => letter.toUpperCase()); }
function statusTone(value?: string | null) { const text = (value || "").toLowerCase(); return text.includes("critical") || text.includes("failed") || text.includes("error") ? "danger" : text.includes("warning") || text.includes("attention") || text.includes("waiting") || text.includes("blocked") ? "warning" : text.includes("healthy") || text.includes("success") || text.includes("valid") || text.includes("active") ? "success" : "neutral"; }

export default function OrchestrationDashboard() {
  const [tab, setTab] = useState<Tab>("overview");
  const [range, setRange] = useState("30d");
  const [summary, setSummary] = useState<any>(null); const [groups, setGroups] = useState<any[]>([]); const [relationships, setRelationships] = useState<any>(null); const [overlap, setOverlap] = useState<any>(null); const [coverage, setCoverage] = useState<any>(null); const [trends, setTrends] = useState<any>(null);
  const [jobs, setJobs] = useState<any[]>([]); const [actions, setActions] = useState<any>(null); const [experiments, setExperiments] = useState<any>(null); const [activity, setActivity] = useState<any>(null); const [enrollment, setEnrollment] = useState<any>(null);
  const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [message, setMessage] = useState("");
  const [overlapMetric, setOverlapMetric] = useState("track"); const [problematicOnly, setProblematicOnly] = useState(false); const [overlapSearch, setOverlapSearch] = useState(""); const [overlapGroup, setOverlapGroup] = useState(""); const [overlapMinimum, setOverlapMinimum] = useState(0); const [overlapSort, setOverlapSort] = useState("name"); const [excludePaused, setExcludePaused] = useState(true); const [excludeExperimentVariants, setExcludeExperimentVariants] = useState(true);
  const [relationshipMode, setRelationshipMode] = useState<"graph" | "table">("graph"); const [relationshipSearch, setRelationshipSearch] = useState(""); const [relationshipGroup, setRelationshipGroup] = useState(""); const [relationshipMinimum, setRelationshipMinimum] = useState(0); const [relationshipHealth, setRelationshipHealth] = useState(""); const [relationshipType, setRelationshipType] = useState(""); const [includePausedRelationships, setIncludePausedRelationships] = useState(false); const [auditSearch, setAuditSearch] = useState("");
  const [wizardStep, setWizardStep] = useState(1); const [goals, setGoals] = useState<string[]>([]); const [automationLevel, setAutomationLevel] = useState("OBSERVE_ONLY"); const [maxTracks, setMaxTracks] = useState(20);
  const [importDocument, setImportDocument] = useState<any>(null); const [importPreview, setImportPreview] = useState<any>(null); const [importMode, setImportMode] = useState<"merge" | "replace">("merge"); const [backupResult, setBackupResult] = useState<any>(null); const [migration, setMigration] = useState<any>(null); const [cleanup, setCleanup] = useState<any>(null);

  const load = useCallback(async (quiet = false) => {
    if (!quiet) setLoading(true); setError("");
    const paths = [`/api/orchestration/summary?range=${range}`, "/api/orchestration/groups", "/api/orchestration/relationships?view=graph&limit=120", "/api/orchestration/overlap?metric=track&excludePaused=true&excludeExperimentVariants=true", "/api/orchestration/coverage?pageSize=12", `/api/orchestration/health-trends?range=${range}`, "/api/orchestration/jobs/upcoming?pageSize=30", "/api/smart-actions?pageSize=12", "/api/experiments?limit=12", "/api/orchestration/activity?pageSize=30", "/api/orchestration/playlists?pageSize=100"];
    const setters = [setSummary, (value: any) => setGroups(value.items || []), setRelationships, setOverlap, setCoverage, setTrends, (value: any) => setJobs(value.items || []), setActions, setExperiments, setActivity, setEnrollment];
    const requests = paths.map((path, index) => request(path).then((value) => setters[index](value)).catch((reason) => { if (index === 0) setError(reason instanceof Error ? reason.message : "Unable to load orchestration summary."); }));
    await Promise.allSettled(requests);
    setLoading(false);
  }, [range]);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => { if (!summary?.preference) return; setRange(summary.range || "30d"); setWizardStep(summary.preference.onboardingStep || 1); setGoals(Array.isArray(summary.preference.goalsJson) ? summary.preference.goalsJson : []); setAutomationLevel(summary.preference.automationLevel || "OBSERVE_ONLY"); const safety = summary.preference.safetySettingsJson; if (safety && typeof safety === "object" && Number(safety.maximumTracksChanged)) setMaxTracks(Number(safety.maximumTracksChanged)); }, [summary]);
  async function act(task: () => Promise<any>, success: string) { setBusy(true); setError(""); setMessage(""); try { const result = await task(); setMessage(success); await load(true); return result; } catch (caught) { setError(caught instanceof Error ? caught.message : "Request failed."); } finally { setBusy(false); } }
  async function changeRange(value: string) { setRange(value); await request("/api/orchestration/preferences", { method: "PATCH", body: JSON.stringify({ dashboardTimeRange: value }) }).catch(() => undefined); }
  async function smartAction(id: string, action: "approve" | "reject" | "apply") { await act(() => request(`/api/smart-actions/${id}/${action}`, { method: "POST", body: JSON.stringify(action === "reject" ? { reason: "Rejected from Playlist Ecosystem" } : {}) }), `Smart Action ${action === "apply" ? "applied" : `${action}d`}.`); }
  async function updatePlaylist(id: string, body: any, success: string) { await act(() => request(`/api/orchestration/playlists/${id}`, { method: "PATCH", body: JSON.stringify(body) }), success); }
  async function cancelJob(id: string) { if (!window.confirm("Cancel this queued occurrence? Its audit history will be preserved.")) return; await act(() => request(`/api/orchestration/jobs/${id}/cancel`, { method: "POST" }), "Queued occurrence cancelled."); }
  async function runNow(job: any) { if (!job.managedPlaylistId) return; await act(() => request("/api/orchestration/jobs", { method: "POST", body: JSON.stringify({ managedPlaylistId: job.managedPlaylistId, jobType: job.jobType, trigger: "MANUAL", dryRun: job.dryRun, idempotencyKey: `dashboard:${job.id}:${Date.now()}` }) }), "A new manual occurrence was queued."); }
  async function refreshRelationships() { setBusy(true); setError(""); try { const query = new URLSearchParams({ view: "graph", limit: "120", search: relationshipSearch, groupId: relationshipGroup, relationshipType, minimumStrength: String(relationshipMinimum), health: relationshipHealth, includePaused: String(includePausedRelationships) }); Array.from(query.entries()).forEach(([key, value]) => { if (!value) query.delete(key); }); setRelationships(await request(`/api/orchestration/relationships?${query}`)); } catch (caught) { setError(caught instanceof Error ? caught.message : "Relationship filters failed."); } finally { setBusy(false); } }
  async function refreshOverlap() { setBusy(true); setError(""); try { const query = new URLSearchParams({ metric: overlapMetric, search: overlapSearch, groupId: overlapGroup, minimum: String(overlapMinimum), sort: overlapSort, excludePaused: String(excludePaused), excludeExperimentVariants: String(excludeExperimentVariants), problematicOnly: String(problematicOnly) }); Array.from(query.entries()).forEach(([key, value]) => { if (!value) query.delete(key); }); setOverlap(await request(`/api/orchestration/overlap?${query}`)); } catch (caught) { setError(caught instanceof Error ? caught.message : "Overlap filters failed."); } finally { setBusy(false); } }
  async function refreshActivity() { setBusy(true); setError(""); try { setActivity(await request(`/api/orchestration/activity?pageSize=30&search=${encodeURIComponent(auditSearch)}`)); } catch (caught) { setError(caught instanceof Error ? caught.message : "Activity search failed."); } finally { setBusy(false); } }

  const metrics = summary ? [
    { label: "Managed playlists", value: summary.summary.managedPlaylists, tab: "health" as Tab, note: `${summary.summary.healthyPlaylists} healthy` },
    { label: "Needs attention", value: summary.summary.needsAttention, tab: "health" as Tab, note: `${summary.summary.criticalPlaylists} critical` },
    { label: "Library coverage", value: pct(summary.summary.libraryCoveragePercentage), tab: "coverage" as Tab, note: summary.summary.coverageDenominator == null ? "Snapshot needed" : `${summary.summary.coverageDenominator.toLocaleString()} eligible tracks` },
    { label: "Average overlap", value: pct(summary.summary.averageOverlapPercentage), tab: "relationships" as Tab, note: `${summary.summary.tracksOverrepresented} excess appearances` },
    { label: "Pending actions", value: summary.summary.pendingSmartActions, tab: "actions" as Tab, note: "Approval-aware" },
    { label: "Active experiments", value: summary.summary.activeExperiments, tab: "experiments" as Tab, note: `${summary.summary.recentlyCompletedExperiments} recently completed` },
    { label: "Upcoming jobs", value: summary.summary.upcomingJobs, tab: "automation" as Tab, note: `${summary.summary.failedOrStalledJobs} failed or stalled` },
    { label: "Automation success", value: pct(summary.summary.automationSuccessRate), tab: "automation" as Tab, note: `${summary.summary.completedJobs} attempts in range` },
  ] : [];
  const heatPlaylists = overlap?.playlists?.slice(0, 12) || [];
  const cellMap = useMemo(() => new Map<string, any>((overlap?.cells || []).flatMap((cell: any) => [[`${cell.playlistAId}:${cell.playlistBId}`, cell], [`${cell.playlistBId}:${cell.playlistAId}`, cell]])), [overlap]);

  return <main className={styles.page}>
    <header className={styles.hero}><div><span className={styles.kicker}><Network size={15}/> Mixarr v2.2.9</span><h1>Playlist Ecosystem</h1><p>Operate every managed Smart Mix playlist as one coordinated, observable system.</p></div><div className={styles.heroActions}><label>History range<select value={range} onChange={(event) => void changeRange(event.target.value)}><option value="7d">Last 7 days</option><option value="30d">Last 30 days</option><option value="90d">Last 90 days</option><option value="all">All history</option></select></label><button onClick={() => void load()} disabled={busy || loading}><RefreshCw size={16}/> Refresh</button></div></header>
    {error && <div className={styles.banner} data-tone="danger"><AlertTriangle size={18}/><span>{error}</span><button onClick={() => void load()}>Retry</button></div>}
    {message && <div className={styles.banner} data-tone="success"><CheckCircle2 size={18}/><span>{message}</span></div>}
    <nav className={styles.tabs} aria-label="Playlist ecosystem sections">{TABS.map((item) => <button key={item.id} aria-current={tab === item.id ? "page" : undefined} onClick={() => setTab(item.id)}>{item.label}</button>)}</nav>
    {loading && !summary ? <DashboardSkeleton/> : <>
      {tab === "overview" && <>
        <section className={styles.metricGrid}>{metrics.map((metric) => <button key={metric.label} onClick={() => setTab(metric.tab)}><span>{metric.label}</span><strong>{metric.value}</strong><small>{metric.note}</small><ArrowRight size={15}/></button>)}</section>
        <div className={styles.twoColumns}><Panel title="Orchestration warnings" icon={<AlertTriangle size={18}/>} action={<button onClick={() => setTab("health")}>View health</button>}><div className={styles.feed}>{!summary?.warnings?.length && <Empty title="No current warnings" text="Mixarr has not detected an orchestration issue in the latest snapshots."/>}{summary?.warnings?.map((warning: any) => <Link href={warning.href} key={warning.id} className={styles.feedItem}><span className={styles.statusDot} data-tone={statusTone(warning.severity)}/><div><strong>{warning.title}</strong><small>{warning.explanation}</small><time>{warning.playlist || "Ecosystem"} · {when(warning.detectedAt)}</time></div></Link>)}</div></Panel>
        <Panel title="Upcoming automation" icon={<Clock3 size={18}/>} action={<button onClick={() => setTab("automation")}>Open queue</button>}><div className={styles.feed}>{!jobs.length && <Empty title="No scheduled work" text="Enabled schedules and queued orchestration jobs will appear here."/>}{jobs.slice(0, 6).map((job) => <article className={styles.feedItem} key={job.id}><span className={styles.statusDot} data-tone={statusTone(job.status)}/><div><strong>{job.managedPlaylist?.displayName || "Historical playlist"}</strong><small>{words(job.jobType)} · {words(job.trigger)}{job.dryRun ? " · dry run" : ""}</small><time>{when(job.scheduledFor)}</time></div></article>)}</div></Panel></div>
        <div className={styles.twoColumns}><TrendPanel trends={trends}/><Panel title="Recent experiment results" icon={<FlaskConical size={18}/>} action={<button onClick={() => setTab("experiments")}>All experiments</button>}><ExperimentList experiments={summary?.recentExperiments || []}/></Panel></div>
      </>}

      {tab === "health" && <>
        <section className={styles.metricGridCompact}>{Object.entries(summary?.healthCounts || {}).map(([state, count]) => <article key={state}><span className={styles.statusDot} data-tone={statusTone(state)}/><div><strong>{count as number}</strong><small>{words(state)}</small></div></article>)}</section>
        <Panel title="Managed playlist health" icon={<HeartPulse size={18}/>} action={<Link href="/playlist-health">Open full health monitor</Link>}><div className={styles.cardGrid}>{summary?.playlists?.map((playlist: any) => <article className={styles.playlistCard} key={playlist.id}><div><span className={styles.badge} data-tone={statusTone(playlist.health.state)}>{words(playlist.health.state)}</span><h3>{playlist.displayName}</h3><p>{playlist.generatedPlaylist?.trackCount || 0} tracks · {playlist.generatedPlaylist?.groupMemberships?.map((row: any) => row.playlistGroup.name).join(", ") || "No group"}</p></div><strong className={styles.score}>{playlist.health.score == null ? "—" : playlist.health.score}</strong><small>{playlist.health.score == null ? "Run a health scan to establish a score." : `${playlist.health.warningCount} warning(s), ${playlist.health.criticalCount} critical issue(s)`}</small><div className={styles.rowActions}><Link href={`/playlist-health?playlistId=${playlist.generatedPlaylistId}`}>Details</Link><button onClick={() => void updatePlaylist(playlist.id, { state: playlist.automationState === "PAUSED" ? "ACTIVE" : "PAUSED", reason: playlist.automationState === "PAUSED" ? null : "Paused from Playlist Ecosystem" }, playlist.automationState === "PAUSED" ? "Playlist resumed." : "Playlist paused.")}>{playlist.automationState === "PAUSED" ? <Play size={14}/> : <Pause size={14}/>} {playlist.automationState === "PAUSED" ? "Resume" : "Pause"}</button></div></article>)}</div></Panel>
        <Panel title="Group health overview" icon={<Grid3X3 size={18}/>} action={<Link href="/playlist-groups">Manage groups</Link>}><ResponsiveTable headers={["Group", "State", "Playlists", "Healthy", "Warnings", "Critical", "Average health", "Overlap", "Coverage", "Actions", "Experiments", "Last / next run"]}>{groups.map((group) => <tr key={group.id}><td><Link href={`/playlist-groups/${group.id}`}><strong>{group.name}</strong></Link></td><td><span className={styles.badge} data-tone={statusTone(group.state)}>{words(group.state)}</span></td><td>{group.playlistCount}</td><td>{group.healthyPlaylistCount}</td><td>{group.warningCount}</td><td>{group.criticalIssueCount}</td><td>{group.averageHealthScore == null ? "—" : Math.round(group.averageHealthScore)}</td><td>{pct(group.averageOverlap)}</td><td>{pct(group.libraryCoverage)}</td><td>{group.pendingSmartActions}</td><td>{group.activeExperiments}</td><td><small>{when(group.lastSuccessfulAutomationRun)}<br/>{when(group.nextScheduledAutomationRun)}</small></td></tr>)}</ResponsiveTable></Panel>
      </>}

      {tab === "relationships" && <>
        <form className={styles.filters} onSubmit={(event) => { event.preventDefault(); void refreshOverlap(); }}><select aria-label="Sort heatmap" value={overlapSort} onChange={(event) => setOverlapSort(event.target.value)}><option value="name">Sort by name</option><option value="group">Sort by group</option><option value="highest_overlap">Highest average overlap</option></select><select aria-label="Filter heatmap by group" value={overlapGroup} onChange={(event) => setOverlapGroup(event.target.value)}><option value="">All groups</option>{groups.map((group) => <option key={group.id} value={group.id}>{group.name}</option>)}</select><input aria-label="Search overlap playlists" value={overlapSearch} onChange={(event) => setOverlapSearch(event.target.value)} placeholder="Search overlap playlists"/><label>Minimum overlap<input type="number" min={0} max={100} value={overlapMinimum} onChange={(event) => setOverlapMinimum(Math.max(0, Math.min(100, Number(event.target.value) || 0)))}/></label><label><input type="checkbox" checked={excludePaused} onChange={(event) => setExcludePaused(event.target.checked)}/> Exclude paused</label><label><input type="checkbox" checked={excludeExperimentVariants} onChange={(event) => setExcludeExperimentVariants(event.target.checked)}/> Exclude variants</label><button disabled={busy}>Apply overlap filters</button></form>
        <Panel title="Playlist relationship graph" icon={<Network size={18}/>} action={<div className={styles.segmented}><button aria-pressed={relationshipMode === "graph"} onClick={() => setRelationshipMode("graph")}>Graph</button><button aria-pressed={relationshipMode === "table"} onClick={() => setRelationshipMode("table")}>Table</button></div>}><form className={styles.filters} onSubmit={(event) => { event.preventDefault(); void refreshRelationships(); }}><input aria-label="Search playlist relationships" value={relationshipSearch} onChange={(event) => setRelationshipSearch(event.target.value)} placeholder="Search playlists"/><select aria-label="Relationship type" value={relationshipType} onChange={(event) => setRelationshipType(event.target.value)}><option value="">All relationships</option><option value="OVERLAP">Overlap</option><option value="DEPENDS_ON">Depends on</option><option value="RUNS_AFTER">Runs after</option><option value="RELATED">Related</option></select><select aria-label="Playlist group" value={relationshipGroup} onChange={(event) => setRelationshipGroup(event.target.value)}><option value="">All groups</option>{groups.map((group) => <option key={group.id} value={group.id}>{group.name}</option>)}</select><select aria-label="Health state" value={relationshipHealth} onChange={(event) => setRelationshipHealth(event.target.value)}><option value="">All health states</option>{["HEALTHY", "WARNING", "NEEDS_ATTENTION", "CRITICAL", "PAUSED", "NOT_ENOUGH_DATA"].map((state) => <option key={state} value={state}>{words(state)}</option>)}</select><label>Minimum strength<input type="number" min={0} max={100} value={relationshipMinimum} onChange={(event) => setRelationshipMinimum(Math.max(0, Math.min(100, Number(event.target.value) || 0)))}/></label><label><input type="checkbox" checked={includePausedRelationships} onChange={(event) => setIncludePausedRelationships(event.target.checked)}/> Include paused</label><button disabled={busy}>Apply filters</button></form><p className={styles.helper}>Explicit dependencies and the strongest cached overlap relationships are shown. This ecosystem view contains managed playlists; bounded edge limits and filters keep large installations responsive.</p>{relationshipMode === "graph" ? <RelationshipGraph data={relationships}/> : <RelationshipTable data={relationships}/>}</Panel>
        <Panel title="Cross-playlist overlap heatmap" icon={<Grid3X3 size={18}/>} action={<div className={styles.filters}><select aria-label="Heatmap metric" value={overlapMetric} onChange={(event) => setOverlapMetric(event.target.value)}><option value="track">Track overlap</option><option value="shared_tracks">Shared tracks</option><option value="artist">Artist overlap</option><option value="album">Album overlap</option><option value="identity">Identity similarity</option></select><label><input type="checkbox" checked={problematicOnly} onChange={(event) => setProblematicOnly(event.target.checked)}/> Problems only</label></div>}><p className={styles.helper}>{overlap?.denominator} {overlap?.note}</p><div className={styles.heatmapWrap}><table className={styles.heatmap}><thead><tr><th>Playlist</th>{heatPlaylists.map((item: any) => <th key={item.id} title={item.name}>{item.name.slice(0, 10)}</th>)}</tr></thead><tbody>{heatPlaylists.map((row: any) => <tr key={row.id}><th>{row.name}</th>{heatPlaylists.map((column: any) => { const cell = cellMap.get(`${row.id}:${column.id}`); const value = row.id === column.id ? null : cell?.value; return <td key={column.id} title={row.id === column.id ? row.name : `${row.name} ↔ ${column.name}: ${value == null ? "not calculated" : value}`} style={value == null ? undefined : { backgroundColor: `rgba(64, 185, 255, ${Math.min(.85, .08 + value / 120)})` }}><Link aria-label={`Compare ${row.name} and ${column.name}`} href={row.id === column.id ? "#" : `/playlist-coordination?playlistAId=${row.id}&playlistBId=${column.id}`}>{row.id === column.id ? "—" : value == null ? "·" : Math.round(value)}</Link></td>})}</tr>)}</tbody></table></div><RelationshipTable data={{ accessibleRows: (overlap?.cells || []).slice(0, 100).map((cell: any) => ({ id: cell.id, sourceName: overlap.playlists.find((item: any) => item.id === cell.playlistAId)?.name, targetName: overlap.playlists.find((item: any) => item.id === cell.playlistBId)?.name, type: cell.withinPolicy ? "Intentional / within policy" : "Problematic overlap", strength: cell.value, trackOverlap: cell.trackOverlap, artistOverlap: cell.artistOverlap, withinPolicy: cell.withinPolicy })) }}/></Panel>
      </>}

      {tab === "coverage" && <><Panel title="Library coverage" icon={<BarChart3 size={18}/>} action={<Link href="/library-coverage">Open coverage dashboard</Link>}><div className={styles.coverageHero}><div className={styles.donut} style={{ "--value": `${coverage?.summary?.snapshot?.coveragePercentage || summary?.summary.libraryCoveragePercentage || 0}%` } as any}><strong>{pct(coverage?.summary?.snapshot?.coveragePercentage ?? summary?.summary.libraryCoveragePercentage)}</strong><span>covered</span></div><div><h3>{coverage?.summary?.snapshot?.usedTracks?.toLocaleString?.() || summary?.summary.coveredTracks?.toLocaleString?.() || "—"} of {coverage?.summary?.snapshot?.eligibleTracks?.toLocaleString?.() || summary?.summary.coverageDenominator?.toLocaleString?.() || "—"} eligible tracks</h3><p>{coverage?.denominator}</p><div className={styles.rowActions}><Link href="/library-coverage?view=opportunities">Review never selected</Link><Link href="/library-coverage?view=overused">Reduce overrepresentation</Link><Link href="/smart-actions">Create discovery action</Link></div></div></div></Panel><Panel title="Coverage segments" icon={<Grid3X3 size={18}/>}><ResponsiveTable headers={["Segment", "Dimension", "Eligible", "Selected", "Coverage", "Never selected", "Opportunities", "Overused"]}>{(coverage?.segments?.items || coverage?.segments || []).map((segment: any) => <tr key={segment.id || `${segment.dimension}:${segment.segmentKey}`}><td><Link href={`/library-coverage?dimension=${segment.dimension}&segment=${encodeURIComponent(segment.segmentKey)}`}>{segment.label}</Link></td><td>{words(segment.dimension)}</td><td>{segment.eligibleTracks}</td><td>{segment.selectedTracks}</td><td>{pct(segment.coveragePercentage)}</td><td>{segment.neverSelectedTracks}</td><td>{segment.opportunityCount}</td><td>{segment.overuseCount}</td></tr>)}</ResponsiveTable></Panel></>}

      {tab === "automation" && <><Panel title="Upcoming automation jobs" icon={<Clock3 size={18}/>} action={<Link href="/jobs">Full job history</Link>}><ResponsiveTable headers={["Job", "Target", "Scheduled", "Trigger", "Status", "Approval / mode", "Last run", "Actions"]}>{jobs.map((job) => <tr key={job.id}><td>{words(job.jobType)}</td><td>{job.managedPlaylist?.displayName || "Historical playlist"}</td><td>{when(job.scheduledFor)}</td><td>{words(job.trigger)}</td><td><span className={styles.badge} data-tone={statusTone(job.status)}>{words(job.status)}</span></td><td>{job.dryRun ? "Dry run" : job.managedPlaylist?.automationEnabled ? "Policy-controlled" : "Manual only"}</td><td>{when(job.managedPlaylist?.lastCompletedAt || job.managedPlaylist?.lastFailedAt)}</td><td><div className={styles.rowActions}><button onClick={() => void runNow(job)}>Run now</button><button onClick={() => void cancelJob(job.id)}>Cancel occurrence</button></div></td></tr>)}</ResponsiveTable></Panel><JobMaintenance capabilities={summary?.capabilities} cleanup={cleanup} setCleanup={setCleanup} act={act}/></>}

      {tab === "actions" && <Panel title="Pending Smart Actions" icon={<Sparkles size={18}/>} action={<Link href="/smart-actions">Open Action Center</Link>}><div className={styles.actionGrid}>{!actions?.items?.length && <Empty title="No pending actions" text="New explainable recommendations will appear here when detected."/>}{actions?.items?.map((action: any) => <article className={styles.actionCard} key={action.id}><div className={styles.cardHeader}><span className={styles.badge} data-tone={action.riskLevel === "HIGH" ? "danger" : action.confidenceLevel === "HIGH" ? "success" : "warning"}>{action.confidenceScore}% · {action.riskLevel} risk</span><span>{words(action.status)}</span></div><h3>{action.title}</h3><p>{action.summary}</p><dl><div><dt>Why</dt><dd>{action.explanation}</dd></div><div><dt>Target</dt><dd>{action.playlist?.plexPlaylistTitle || action.library?.name || "Library"}</dd></div><div><dt>Rollback</dt><dd>{action.playlistId ? "Playlist version retained" : "Depends on action type"}</dd></div></dl><div className={styles.rowActions}>{action.status === "PENDING" && <button onClick={() => void smartAction(action.id, "approve")}><CheckCircle2 size={14}/> Approve</button>}{action.status === "PENDING" && <button onClick={() => void smartAction(action.id, "reject")}>Reject</button>}{["APPROVED", "SCHEDULED"].includes(action.status) && <button onClick={() => void smartAction(action.id, "apply")}><Play size={14}/> Apply</button>}<Link href={`/smart-actions?selected=${action.id}`}>Review</Link></div></article>)}</div></Panel>}

      {tab === "experiments" && <Panel title="Smart Experiments" icon={<FlaskConical size={18}/>} action={<Link href="/experiments">Experiment workspace</Link>}><div className={styles.cardGrid}>{!experiments?.items?.length && <Empty title="No experiments" text="Create a controlled A/B comparison from the experiment workspace."/>}{experiments?.items?.map((experiment: any) => <article className={styles.playlistCard} key={experiment.id}><div><span className={styles.badge} data-tone={statusTone(experiment.status)}>{words(experiment.status)}</span><h3>{experiment.name}</h3><p>{experiment.sourcePlaylist?.plexPlaylistTitle}</p></div><dl><div><dt>Suggested winner</dt><dd>{experiment.suggestedWinner || "Awaiting evidence"}</dd></div><div><dt>Confidence</dt><dd>{experiment.winnerConfidence || "Not enough data"}</dd></div><div><dt>Planned end</dt><dd>{when(experiment.plannedEndAt)}</dd></div></dl><div className={styles.rowActions}><Link href={`/experiments/${experiment.id}`}>Open results</Link></div></article>)}</div></Panel>}

      {tab === "activity" && <Panel title="Recent automated changes and audit events" icon={<Activity size={18}/>} action={<form onSubmit={(event) => { event.preventDefault(); void refreshActivity(); }} className={styles.filters}><input aria-label="Search event summaries" value={auditSearch} onChange={(event) => setAuditSearch(event.target.value)} placeholder="Search event summaries"/><button disabled={busy}>Search</button></form>}>
        <div className={styles.timeline}>{!activity?.items?.length && <Empty title="No matching activity" text="Automated changes are recorded with their source, reason, target, and related job."/>}{activity?.items?.map((event: any) => <article key={event.id}><span className={styles.statusDot} data-tone={statusTone(event.outcome || event.severity)}/><div><div className={styles.cardHeader}><strong>{words(event.eventType)}</strong><time>{when(event.createdAt)}</time></div><p>{event.message}</p><small>{words(event.actorType)}{event.actorId ? ` · ${event.actorId}` : ""}{event.managedPlaylist ? ` · ${event.managedPlaylist.displayName}` : ""}{event.job ? ` · ${words(event.job.jobType)} job ${event.job.status.toLowerCase()}` : ""}</small><details><summary>Audit details</summary><dl><div><dt>Operation</dt><dd>{event.operationType ? words(event.operationType) : "Not specified"}</dd></div><div><dt>Outcome</dt><dd>{event.outcome || "Not specified"}</dd></div><div><dt>Severity</dt><dd>{event.severity}</dd></div><div><dt>Related Smart Action</dt><dd>{event.smartActionId || "None"}</dd></div><div><dt>Related experiment</dt><dd>{event.experimentId || "None"}</dd></div><div><dt>Related group</dt><dd>{event.playlistGroupId || "None"}</dd></div></dl>{event.metadataJson && <pre>{JSON.stringify(event.metadataJson, null, 2)}</pre>}<div className={styles.rowActions}><a href={`/api/orchestration/audit/${event.id}`}>Open full audit record</a>{event.restoreAvailable && event.managedPlaylist?.generatedPlaylistId && <Link href={`/generated-playlists/${event.managedPlaylist.generatedPlaylistId}/versions`}>Review rollback versions</Link>}</div></details></div></article>)}</div>
        <Pagination pagination={activity?.pagination}/>
      </Panel>}

      {tab === "setup" && <SetupAndSafety summary={summary} enrollment={enrollment} wizardStep={wizardStep} setWizardStep={setWizardStep} goals={goals} setGoals={setGoals} automationLevel={automationLevel} setAutomationLevel={setAutomationLevel} maxTracks={maxTracks} setMaxTracks={setMaxTracks} act={act} importDocument={importDocument} setImportDocument={setImportDocument} importPreview={importPreview} setImportPreview={setImportPreview} importMode={importMode} setImportMode={setImportMode} backupResult={backupResult} setBackupResult={setBackupResult} migration={migration} setMigration={setMigration}/>} 
    </>}
  </main>;
}

function Panel({ title, icon, action, children }: { title: string; icon: React.ReactNode; action?: React.ReactNode; children: React.ReactNode }) { return <section className={styles.panel}><header className={styles.panelHeader}><div><span>{icon}</span><h2>{title}</h2></div>{action}</header>{children}</section>; }
function Empty({ title, text }: { title: string; text: string }) { return <div className={styles.empty}><strong>{title}</strong><p>{text}</p></div>; }
function ResponsiveTable({ headers, children }: { headers: string[]; children: React.ReactNode }) { return <div className={styles.tableWrap}><table><thead><tr>{headers.map((header) => <th key={header}>{header}</th>)}</tr></thead><tbody>{children}</tbody></table></div>; }
function Pagination({ pagination }: { pagination?: any }) { if (!pagination || pagination.pages <= 1) return null; return <p className={styles.helper}>Showing page {pagination.page} of {pagination.pages} · {pagination.total} events. Use API pagination parameters for older results.</p>; }
function DashboardSkeleton() { return <div className={styles.skeletonGrid}>{Array.from({ length: 8 }, (_, index) => <div key={index}/>)}</div>; }
function ExperimentList({ experiments }: { experiments: any[] }) { return <div className={styles.feed}>{!experiments.length && <Empty title="No completed experiments" text="Completed and inconclusive results will appear here."/>}{experiments.map((item) => <Link href={`/experiments/${item.id}`} key={item.id} className={styles.feedItem}><span className={styles.statusDot} data-tone={statusTone(item.status)}/><div><strong>{item.name}</strong><small>{item.sourcePlaylist?.plexPlaylistTitle} · Winner {item.suggestedWinner || "not selected"}</small><time>{when(item.completedAt)}</time></div></Link>)}</div>; }
function TrendPanel({ trends }: { trends: any }) { const items = trends?.items || []; const values = items.map((item: any) => item.averageHealthScore).filter((value: any) => value != null); const points = values.length > 1 ? values.map((value: number, index: number) => `${(index / (values.length - 1)) * 100},${100 - value}`).join(" ") : ""; return <Panel title="Ecosystem trends" icon={<BarChart3 size={18}/>}><div className={styles.chart} aria-label="Average playlist health trend">{points ? <svg viewBox="0 0 100 100" preserveAspectRatio="none" role="img"><polyline points={points}/></svg> : <Empty title="Trend history is building" text={trends?.note || "Additional ecosystem snapshots are needed for a truthful trend."}/>}</div>{items.length > 0 && <ResponsiveTable headers={["Snapshot", "Health", "Coverage", "Overlap", "Success", "Pending actions"]}>{items.slice(-8).map((item: any) => <tr key={item.id}><td>{when(item.capturedAt)}</td><td>{item.averageHealthScore == null ? "—" : Math.round(item.averageHealthScore)}</td><td>{pct(item.libraryCoveragePercentage)}</td><td>{pct(item.averageOverlapPercentage)}</td><td>{pct(item.automationSuccessRate)}</td><td>{item.pendingSmartActionCount}</td></tr>)}</ResponsiveTable>}</Panel>; }
function RelationshipGraph({ data }: { data: any }) {
  const nodes = (data?.nodes || []).slice(0, 30);
  const nodeSet = new Set(nodes.map((node: any) => node.id));
  const edges = (data?.edges || []).filter((edge: any) => nodeSet.has(edge.source) && nodeSet.has(edge.target)).slice(0, 80);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const selected = nodes.find((node: any) => node.id === selectedId);
  const selectedEdges = selected ? edges.filter((edge: any) => edge.source === selected.id || edge.target === selected.id).slice(0, 5) : [];
  const positions = new Map(nodes.map((node: any, index: number) => { const angle = (index / Math.max(1, nodes.length)) * Math.PI * 2; return [node.id, { x: 50 + Math.cos(angle) * 39, y: 50 + Math.sin(angle) * 39 }]; }));
  return <>
    <div className={styles.desktopGraph}>
      <div className={styles.graph} role="img" aria-label={`Relationship graph showing ${nodes.length} playlist nodes and ${edges.length} strongest edges`}><svg viewBox="0 0 100 100">{edges.map((edge: any) => { const a: any = positions.get(edge.source), b: any = positions.get(edge.target); return a && b ? <line key={edge.id} x1={a.x} y1={a.y} x2={b.x} y2={b.y} opacity={Math.max(.15, edge.strength / 100)}/> : null; })}{nodes.map((node: any) => { const point: any = positions.get(node.id); return <g key={node.id} role="button" tabIndex={0} aria-label={`Inspect ${node.name}`} transform={`translate(${point.x} ${point.y})`} onClick={() => setSelectedId(node.id)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") setSelectedId(node.id); }}><circle r={selectedId === node.id ? "4.2" : "3.2"} data-tone={statusTone(node.health)}/><title>{node.name} · {words(node.health)} · {node.trackCount} tracks</title></g>; })}</svg><div className={styles.graphLabels}>{nodes.slice(0, 12).map((node: any) => <button key={node.id} onClick={() => setSelectedId(node.id)}><i data-tone={statusTone(node.health)}/>{node.name}</button>)}</div></div>
      {selected && <aside className={styles.nodeDetails}><div className={styles.cardHeader}><h3>{selected.name}</h3><span className={styles.badge} data-tone={statusTone(selected.health)}>{words(selected.health)}</span></div><dl><div><dt>Tracks</dt><dd>{selected.trackCount}</dd></div><div><dt>Groups</dt><dd>{selected.groups?.map((group: any) => group.name).join(", ") || "No group"}</dd></div><div><dt>Identity</dt><dd>{selected.identitySummary || "Not enough data"}</dd></div><div><dt>Active experiments</dt><dd>{selected.activeExperiments}</dd></div><div><dt>Pending actions</dt><dd>{selected.pendingActions}</dd></div><div><dt>Strongest overlap</dt><dd>{selectedEdges.length ? pct(Math.max(...selectedEdges.map((edge: any) => edge.trackOverlap || 0))) : "No cached relationship"}</dd></div></dl>{selectedEdges.length > 0 && <p className={styles.helper}>Strongest relationships: {selectedEdges.map((edge: any) => { const otherId = edge.source === selected.id ? edge.target : edge.source; return `${nodes.find((node: any) => node.id === otherId)?.name || "Unknown"} (${Math.round(edge.strength)}%)`; }).join(", ")}</p>}</aside>}
    </div>
    <div className={styles.mobileGraphTable}><p className={styles.helper}>The relationship table is shown on narrow screens for touch-friendly navigation.</p><RelationshipTable data={data}/></div>
    {data?.limits?.nodesLimited && <p className={styles.helper}>The graph is simplified to the first {data.limits.nodeLimit} filtered nodes and strongest {data.limits.edgeLimit} edges. Use the table and filters for the complete bounded result.</p>}
  </>;
}
function RelationshipTable({ data }: { data: any }) { return <ResponsiveTable headers={["Playlist A", "Relationship", "Playlist B", "Strength", "Track overlap", "Artist overlap", "Policy"]}>{(data?.accessibleRows || []).slice(0, 100).map((row: any) => <tr key={row.id}><td>{row.sourceName}</td><td>{words(row.type)}</td><td>{row.targetName}</td><td>{pct(row.strength)}</td><td>{pct(row.trackOverlap)}</td><td>{pct(row.artistOverlap)}</td><td>{row.withinPolicy ? "Within policy" : "Review"}</td></tr>)}</ResponsiveTable>; }

function JobMaintenance({ capabilities, cleanup, setCleanup, act }: any) { async function preview() { try { setCleanup(await request("/api/orchestration/jobs/maintenance")); } catch (error) { setCleanup({ error: error instanceof Error ? error.message : "Unavailable" }); } } async function run(action: string) { if (!window.confirm(`Confirm ${action.replaceAll("_", " ")} for the displayed scope? Audit records will be preserved.`)) return; await act(() => request("/api/orchestration/jobs/maintenance", { method: "POST", body: JSON.stringify({ action, confirm: true }) }), "Queue maintenance completed."); await preview(); } if (!capabilities?.clearJobHistory) return null; return <Panel title="Queue cleanup" icon={<Settings2 size={18}/>} action={<button onClick={() => void preview()}>Preview scope</button>}>{cleanup?.error ? <p className={styles.helper}>{cleanup.error}</p> : cleanup?.counts ? <><div className={styles.metricGridCompact}>{Object.entries(cleanup.counts).map(([key, value]) => <article key={key}><strong>{value as number}</strong><small>{words(key)}</small></article>)}</div><p className={styles.helper}>Retention: {cleanup.retention.jobHistoryDays} days for jobs, {cleanup.retention.auditDays} days for audit. Cleanup never deletes explanatory audit records.</p><div className={styles.rowActions}>{["clear_completed", "clear_failed", "retry_failed", "cancel_queued", "remove_stale", "requeue_interrupted"].map((action) => <button key={action} onClick={() => void run(action)}>{words(action)}</button>)}</div></> : <Empty title="Preview queue maintenance" text="Counts are loaded only when requested; no jobs are changed by preview."/>}</Panel>; }

function SetupAndSafety(props: any) { const { summary, enrollment, wizardStep, setWizardStep, goals, setGoals, automationLevel, setAutomationLevel, maxTracks, setMaxTracks, act, importDocument, setImportDocument, importPreview, setImportPreview, importMode, setImportMode, backupResult, setBackupResult, migration, setMigration } = props; const goalOptions = ["Improve library coverage", "Reduce playlist overlap", "Preserve playlist identities", "Increase discovery", "Improve BPM flow", "Improve mood flow", "Keep playlists fresh", "Reduce repeated artists"];
  const [selectedPlaylist, setSelectedPlaylist] = useState(""); const [selectedLibrary, setSelectedLibrary] = useState(""); const [enrollmentMode, setEnrollmentMode] = useState("COORDINATED");
  useEffect(() => { if (!selectedPlaylist && enrollment?.available?.[0]) setSelectedPlaylist(enrollment.available[0].id); if (!selectedLibrary && enrollment?.libraries?.[0]) setSelectedLibrary(enrollment.libraries[0].id); }, [enrollment, selectedLibrary, selectedPlaylist]);
  async function saveWizard(complete = false) { await act(() => request("/api/orchestration/preferences", { method: "PATCH", body: JSON.stringify({ onboardingStep: wizardStep, onboardingComplete: complete, goals, automationLevel, safetySettings: { maximumTracksChanged: maxTracks, approvalRequired: true, rollbackRetention: 30, quietHours: true, maximumSimultaneousJobs: 1 } }) }), complete ? "Orchestration review saved. Existing automation remains subject to its explicit runtime settings." : "Setup progress saved."); }
  async function fileJson(file: File | undefined, callback: (value: any) => void) { if (!file) return; if (file.size > 25 * 1024 * 1024) throw new Error("Configuration files must be 25 MiB or smaller."); callback(JSON.parse(await file.text())); }
  async function previewImport() { const value = await request("/api/orchestration/configuration/import/preview", { method: "POST", body: JSON.stringify({ configuration: importDocument, mode: importMode }) }); setImportPreview(value); }
  async function applyImport() { if (!window.confirm(`Apply the reviewed ${importMode} import? Only orchestration configuration is in scope.`)) return; await act(() => request("/api/orchestration/configuration/import", { method: "POST", body: JSON.stringify({ configuration: importDocument, mode: importMode, confirm: true }) }), "Configuration import completed and was audited."); }
  async function enrollPlaylist() { const result = await act(() => request("/api/orchestration/playlists", { method: "POST", body: JSON.stringify({ generatedPlaylistId: selectedPlaylist, libraryId: selectedLibrary, automationEnabled: false }) }), "Playlist enrolled with automation disabled."); const id = result?.playlist?.id; if (id && enrollmentMode !== "COORDINATED") await request(`/api/orchestration/playlists/${id}`, { method: "PATCH", body: JSON.stringify({ orchestrationMode: enrollmentMode }) }); setSelectedPlaylist(""); }
  return <><Panel title="Orchestration onboarding and configuration review" icon={<ShieldCheck size={18}/>} action={<span className={styles.badge} data-tone={summary?.preference?.onboardingComplete ? "success" : "warning"}>{summary?.preference?.onboardingComplete ? "Configured" : `Step ${wizardStep} of 6`}</span>}><div className={styles.wizardSteps}>{["Introduction", "Select playlists", "Define goals", "Automation level", "Safety", "Review"].map((label, index) => <button key={label} aria-current={wizardStep === index + 1 ? "step" : undefined} onClick={() => setWizardStep(index + 1)}><span>{index + 1}</span>{label}</button>)}</div><div className={styles.wizardBody}>{wizardStep === 1 && <div><h3>Coordinate without giving up control</h3><p>Mixarr can observe health, suggest changes, or automate only within explicit limits. Smart Actions keep explanations and approvals visible; playlist-version snapshots support rollback when an action changes a playlist.</p></div>}{wizardStep === 2 && <div><h3>Select playlists</h3><p>Enrollment is explicit. Existing unmanaged playlists are not changed until you register them.</p><ResponsiveTable headers={["Playlist", "Tracks", "Enrollment"]}>{(enrollment?.items || []).map((item: any) => <tr key={item.id}><td>{item.displayName}</td><td>{item.generatedPlaylist?.trackCount || 0}</td><td>{words(item.orchestrationMode)}</td></tr>)}</ResponsiveTable>{enrollment?.available?.length ? <div className={styles.choiceGrid}><label className={styles.field}>Playlist<select value={selectedPlaylist} onChange={(event) => setSelectedPlaylist(event.target.value)}>{enrollment.available.map((item: any) => <option key={item.id} value={item.id}>{item.plexPlaylistTitle} ({item.trackCount} tracks)</option>)}</select></label><label className={styles.field}>Music library<select value={selectedLibrary} onChange={(event) => setSelectedLibrary(event.target.value)}>{(enrollment.libraries || []).map((item: any) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className={styles.field}>Orchestration mode<select value={enrollmentMode} onChange={(event) => setEnrollmentMode(event.target.value)}><option value="COORDINATED">Coordinated</option><option value="OBSERVE_ONLY">Observe only</option><option value="DRY_RUN_ONLY">Dry run only</option></select></label><button disabled={!selectedPlaylist || !selectedLibrary} onClick={() => void enrollPlaylist()}>Enroll with automation disabled</button></div> : <p className={styles.helper}>No eligible unmanaged playlists are currently available.</p>}</div>}{wizardStep === 3 && <div><h3>Define ecosystem goals</h3><div className={styles.choiceGrid}>{goalOptions.map((goal) => <label key={goal}><input type="checkbox" checked={goals.includes(goal)} onChange={(event) => setGoals(event.target.checked ? [...goals, goal] : goals.filter((item: string) => item !== goal))}/>{goal}</label>)}</div></div>}{wizardStep === 4 && <div><h3>Choose an automation level</h3><div className={styles.choiceGrid}>{[["OBSERVE_ONLY", "Observe only"], ["SUGGEST", "Suggest actions"], ["SAFE_AUTO", "Apply safe actions automatically"], ["FULL_LIMITED", "Fully automated within limits"]].map(([value, label]) => <label key={value}><input type="radio" name="automation-level" value={value} checked={automationLevel === value} onChange={() => setAutomationLevel(value)}/><span><strong>{label}</strong><small>Runtime automation still requires the corresponding global and playlist settings.</small></span></label>)}</div></div>}{wizardStep === 5 && <div><h3>Safety settings</h3><label className={styles.field}>Maximum tracks changed per run<input type="number" min={1} max={500} value={maxTracks} onChange={(event) => setMaxTracks(Math.max(1, Math.min(500, Number(event.target.value) || 1)))}/></label><ul><li>High-risk Smart Actions require individual review.</li><li>Rollback retention defaults to 30 days.</li><li>Only one orchestration job runs concurrently by default.</li><li>Protected and locked tracks remain protected.</li></ul></div>}{wizardStep === 6 && <div><h3>Review</h3><dl><div><dt>Managed playlists</dt><dd>{summary?.summary.managedPlaylists}</dd></div><div><dt>Goals</dt><dd>{goals.join(", ") || "No optional goals selected"}</dd></div><div><dt>Automation level</dt><dd>{words(automationLevel)}</dd></div><div><dt>Maximum change scope</dt><dd>{maxTracks} tracks per run</dd></div><div><dt>Approvals</dt><dd>Required for high-risk actions</dd></div></dl></div>}</div><div className={styles.wizardActions}><button disabled={wizardStep === 1} onClick={() => setWizardStep(Math.max(1, wizardStep - 1))}>Back</button><button onClick={() => void saveWizard(false)}>Save progress</button>{wizardStep < 6 ? <button onClick={() => setWizardStep(Math.min(6, wizardStep + 1))}>Continue</button> : <button onClick={() => void saveWizard(true)}><CheckCircle2 size={15}/> Save review</button>}</div></Panel>
  <div className={styles.twoColumns}><Panel title="Export and import" icon={<Download size={18}/>}><p className={styles.helper}>Exports use an allowlist and exclude credentials, tokens, sessions, API keys, encrypted endpoints, and private encryption material.</p><div className={styles.rowActions}><a className={styles.buttonLink} href="/api/orchestration/configuration/export"><Download size={14}/> Export JSON</a>{summary?.capabilities.importConfiguration && <label className={styles.buttonLink}><Upload size={14}/> Choose import<input type="file" accept="application/json,.json" onChange={(event) => void fileJson(event.target.files?.[0], (value) => { setImportDocument(value); setImportPreview(null); })}/></label>}</div>{importDocument && <div className={styles.importBox}><label>Import mode<select value={importMode} onChange={(event) => { setImportMode(event.target.value as any); setImportPreview(null); }}><option value="merge">Merge</option><option value="replace">Replace orchestration settings</option></select></label><button onClick={() => void previewImport()}>Validate and preview</button>{importPreview && <><p><strong>{importPreview.valid ? "Valid configuration" : "Invalid"}</strong> · {importPreview.counts.managedPlaylists} playlists · {importPreview.counts.playlistGroups} groups · {importPreview.missingPlaylists.length} missing references</p>{importPreview.warnings?.map((warning: string) => <p key={warning} className={styles.warningText}>{warning}</p>)}<button onClick={() => void applyImport()}>Confirm reviewed import</button></>}</div>}</Panel>
  <Panel title="Backup and migration readiness" icon={<ShieldCheck size={18}/>}><p className={styles.helper}>Validation inspects section integrity without modifying the active database.</p>{summary?.capabilities.validateBackups && <label className={styles.buttonLink}><Upload size={14}/> Validate backup manifest<input type="file" accept="application/json,.json" onChange={(event) => void fileJson(event.target.files?.[0], async (value) => setBackupResult(await request("/api/orchestration/backup/validate", { method: "POST", body: JSON.stringify({ backup: value, sourceName: event.target.files?.[0]?.name }) })))}/></label>}{backupResult && <p><span className={styles.badge} data-tone={statusTone(backupResult.status)}>{backupResult.status}</span> {backupResult.restoreCompatible ? "Restore compatible" : "Not restore ready"} · {backupResult.estimatedRestoreScope} estimated records</p>}{summary?.capabilities.importConfiguration && <button onClick={async () => setMigration(await request("/api/orchestration/migration-checks"))}>Run v2.2.x migration checks</button>}{migration && <div className={styles.checks}>{migration.checks.map((check: any) => <article key={check.key}><span className={styles.statusDot} data-tone={statusTone(check.status)}/><div><strong>{check.message}</strong>{check.action && <small>{check.action}</small>}</div></article>)}</div>}</Panel></div></>;
}
